<?php require_once dirname(__DIR__) . '/app/config.php'; if(user()) redirect('index.php'); $mode=$_GET['mode']??'login';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'login';$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';
 if($action==='register'){$name=trim($_POST['name']??'');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){flash('danger','Vui lòng nhập họ tên, email hợp lệ và mật khẩu tối thiểu 8 ký tự.');redirect('auth.php?mode=register');}
 try{$st=$pdo->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'user')");$st->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$_SESSION['user']=['id'=>$id,'name'=>$name,'email'=>$email,'role'=>'user'];session_regenerate_id(true);flash('success','Đăng ký thành công.');redirect('index.php');}catch(PDOException $e){flash('danger','Email đã được sử dụng hoặc không thể tạo tài khoản.');redirect('auth.php?mode=register');}}
 $st=$pdo->prepare("SELECT * FROM users WHERE email=? AND status='active'");$st->execute([$email]);$u=$st->fetch();if($u&&password_verify($pass,$u['password'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];flash('success','Đăng nhập thành công.');redirect($u['role']==='admin'?'admin.php':'index.php');}flash('danger','Email hoặc mật khẩu không chính xác.');redirect('auth.php');
}
header_html('Tài khoản'); ?>
<div class="row justify-content-center"><div class="col-md-7 col-lg-5"><div class="card p-4 shadow-sm border-0"><h2 class="fw-bold text-center">IT-<span class="text-primary">Books</span></h2><p class="text-muted text-center">Tài khoản học tập của bạn</p><ul class="nav nav-pills nav-fill mb-4"><li class="nav-item"><a class="nav-link <?=$mode!=='register'?'active':''?>" href="auth.php">Đăng nhập</a></li><li class="nav-item"><a class="nav-link <?=$mode==='register'?'active':''?>" href="auth.php?mode=register">Đăng ký</a></li></ul><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="<?=$mode==='register'?'register':'login'?>"><?php if($mode==='register'):?><label class="form-label">Họ và tên</label><input class="form-control mb-3" name="name" required><?php endif;?><label class="form-label">Email</label><input class="form-control mb-3" type="email" name="email" required><label class="form-label">Mật khẩu</label><input class="form-control mb-3" type="password" name="password" minlength="<?=$mode==='register'?8:1?>" required><?php if($mode==='register'):?><div class="form-text mb-3">Mật khẩu tối thiểu 8 ký tự.</div><?php endif;?><button class="btn btn-primary w-100 py-2"><?=$mode==='register'?'Tạo tài khoản':'Đăng nhập'?></button></form></div></div></div>
<?php footer_html(); ?>
